	if err := json.Unmarshal(b, &m); err != nil {
		return nil, err
	}
	if raw, ok := m["User"]; ok {
		var v rt.Maybe[string]
		if json.Unmarshal(raw, &v) == nil {
			s.User = v
		}
	}
